```javascript run
const daftarTugas = [
  { id: 1, teks: "A", selesai: true },
  { id: 2, teks: "B", selesai: false },
  { id: 3, teks: "C", selesai: true },
  { id: 4, teks: "D", selesai: false },
];

function hitungStatistik(daftar) {
  const totalTugas = daftar.length;
  const tugasSelesai = daftar.filter(t => t.selesai).length;
  const tugasBelumSelesai = totalTugas - tugasSelesai;
  const persenSelesai = totalTugas === 0 ? 0 : Math.round((tugasSelesai / totalTugas) * 100);

  return { totalTugas, tugasSelesai, tugasBelumSelesai, persenSelesai };
}

console.log(hitungStatistik(daftarTugas));
```

Perhatikan `daftar.filter(t => t.selesai).length`. `filter` mengembalikan array tugas yang selesai, dan kita langsung mengambil `.length` dari hasilnya, tanpa menyimpannya ke variabel sementara.

